code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    uniform = Counter(row[0] for row in grid if all(v == row[0] for v in row))
    background = uniform.most_common(1)[0][0] if uniform else Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row}
    foregrounds = [v for v in colors if v != background]
    if not foregrounds:
        return out
    foreground = max(foregrounds, key=lambda c: sum(row.count(c) for row in grid))

    # Continue clear alternating bands to the right, marking missing foreground cells.
    found_alternating = False
    for i, row in enumerate(grid):
        best = None
        for start in range(w):
            if start + 1 >= w or row[start] == row[start + 1]:
                continue
            a, b = row[start], row[start + 1]
            if background not in (a, b):
                continue
            end = start + 2
            while end < w and row[end] == (a if (end - start) % 2 == 0 else b):
                end += 1
            if end - start >= 4 and (best is None or end - start > best[1] - best[0]):
                best = (start, end, a, b)
        if best is not None:
            found_alternating = True
            start, end, a, b = best
            for j in range(end, w):
                expected = a if (j - start) % 2 == 0 else b
                if row[j] == background and expected != background:
                    out[i][j] = 1
    if found_alternating:
        return out

    # Compare equally tall separated patterned blocks and mark missing foreground cells.
    bands = []
    r = 0
    while r < h:
        if len(set(grid[r])) == 1:
            r += 1
            continue
        start = r
        while r < h and len(set(grid[r])) > 1:
            r += 1
        bands.append((start, r))
    if len(bands) == 2 and bands[0][1] - bands[0][0] == bands[1][1] - bands[1][0]:
        (a, b), (c, d) = bands
        ca = sum(row.count(foreground) for row in grid[a:b])
        cb = sum(row.count(foreground) for row in grid[c:d])
        small, large = ((a, b), (c, d)) if ca <= cb else ((c, d), (a, b))
        for rr in range(small[1] - small[0]):
            for j in range(w):
                if grid[small[0] + rr][j] == background and grid[large[0] + rr][j] == foreground:
                    out[small[0] + rr][j] = 1
        return out

    # Stripe-like rows extend their foreground color through the trailing background.
    for i, row in enumerate(grid):
        if background in row and foreground in row:
            last = max(j for j, v in enumerate(row) if v == foreground)
            for j in range(last + 1, w):
                if row[j] == background:
                    out[i][j] = 1
    return out
'''
